import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;

/**
 * Offline link check of mod jars against an intermediary Minecraft jar.
 * Usage: java -cp asm+asm-tree LinkCheck.java <mcJar> <modsDir> <targetJarSubstring>...
 * Reports, for classes in target jars:
 *   ABSTRACT  concrete class leaves an abstract method unimplemented (AbstractMethodError)
 *   METHOD    a call whose method does not exist in the owner hierarchy (NoSuchMethodError)
 *   FIELD     a field access that does not resolve (NoSuchFieldError)
 *   NOCLASS   a referenced owner class that exists nowhere (NoClassDefFoundError if reached)
 */
public class LinkCheck {
    static final Map<String, ClassNode> classes = new HashMap<>();
    static final Set<String> targets = new TreeSet<>();
    static final Map<String, List<ClassNode>> mixinsByTarget = new HashMap<>();
    static final Set<String> mixinClasses = new HashSet<>();

    public static void main(String[] a) throws Exception {
        load(Files.readAllBytes(Path.of(a[0])), false);
        List<String> tsubs = Arrays.asList(a).subList(2, a.length);
        try (var s = Files.list(Path.of(a[1]))) {
            for (Path p : s.filter(p -> p.toString().endsWith(".jar")).toList()) {
                boolean t = tsubs.stream().anyMatch(x -> p.getFileName().toString().contains(x));
                load(Files.readAllBytes(p), t);
            }
        }
        // merge mixins into their targets
        for (ClassNode cn : new ArrayList<>(classes.values())) {
            for (String tgt : mixinTargets(cn)) {
                mixinClasses.add(cn.name);
                mixinsByTarget.computeIfAbsent(tgt, k -> new ArrayList<>()).add(cn);
            }
        }
        Map<String, Set<String>> out = new TreeMap<>();
        for (String t : targets) {
            ClassNode cn = classes.get(t);
            if (mixinClasses.contains(t)) continue; // mixin bodies are merged elsewhere
            checkAbstract(cn, out);
            checkRefs(cn, out);
        }
        int n = 0;
        for (var e : out.entrySet()) for (String m : e.getValue()) { System.out.println(m); n++; }
        System.out.println("TOTAL " + n + " findings over " + targets.size() + " classes");
    }

    static void load(byte[] jar, boolean target) throws IOException {
        try (ZipInputStream z = new ZipInputStream(new ByteArrayInputStream(jar))) {
            ZipEntry e;
            while ((e = z.getNextEntry()) != null) {
                String n = e.getName();
                if (n.endsWith(".jar")) { load(z.readAllBytes(), target); continue; }
                if (!n.endsWith(".class") || n.startsWith("META-INF/versions/")) continue;
                ClassNode cn = new ClassNode();
                try { new ClassReader(z.readAllBytes()).accept(cn, ClassReader.SKIP_FRAMES); } catch (Exception ex) { continue; }
                if (n.equals("module-info.class")) continue;
                classes.putIfAbsent(cn.name, cn);
                if (target) targets.add(cn.name);
            }
        }
    }

    static List<String> mixinTargets(ClassNode cn) {
        List<String> r = new ArrayList<>();
        List<AnnotationNode> anns = new ArrayList<>();
        if (cn.invisibleAnnotations != null) anns.addAll(cn.invisibleAnnotations);
        if (cn.visibleAnnotations != null) anns.addAll(cn.visibleAnnotations);
        for (AnnotationNode an : anns) {
            if (!an.desc.equals("Lorg/spongepowered/asm/mixin/Mixin;") || an.values == null) continue;
            for (int i = 0; i < an.values.size(); i += 2) {
                Object v = an.values.get(i + 1);
                if (v instanceof List<?> l) for (Object o : l) {
                    if (o instanceof Type ty) r.add(ty.getInternalName());
                    else if (o instanceof String s) r.add(s.replace('.', '/'));
                }
            }
        }
        return r;
    }

    static ClassNode get(String name) {
        ClassNode cn = classes.get(name);
        if (cn != null) return cn;
        try (InputStream in = ClassLoader.getSystemResourceAsStream(name + ".class")) {
            if (in == null) return null;
            cn = new ClassNode();
            new ClassReader(in.readAllBytes()).accept(cn, ClassReader.SKIP_CODE);
            classes.put(name, cn);
            return cn;
        } catch (IOException ex) { return null; }
    }

    /** interfaces of a class including mixin-added ones */
    static List<String> interfacesOf(ClassNode cn) {
        List<String> r = new ArrayList<>(cn.interfaces);
        for (ClassNode m : mixinsByTarget.getOrDefault(cn.name, List.of())) r.addAll(m.interfaces);
        return r;
    }

    static List<MethodNode> methodsOf(ClassNode cn) {
        List<MethodNode> r = new ArrayList<>(cn.methods);
