                if (n.endsWith(".jar")) { load(z.readAllBytes(), target); continue; }
                if (!n.endsWith(".class") || n.startsWith("META-INF/versions/")) continue;
                ClassNode cn = new ClassNode();
                try { new ClassReader(z.readAllBytes()).accept(cn, ClassReader.SKIP_FRAMES); } catch (Exception ex) { continue; }
