        out.forEach((k, v) -> System.out.println(k + " -> " + v));
        System.out.println("TOTAL " + out.size());
    }
    static boolean client(String n) {
        return n.startsWith("net/minecraft/client/") || n.startsWith("com/zurrtum/create/client/") || n.startsWith("com/mojang/blaze3d/");
    }
    static void scan(byte[] jar, Map<String, Set<String>> out) throws IOException {
        try (ZipInputStream z = new ZipInputStream(new ByteArrayInputStream(jar))) {
            ZipEntry e;
            while ((e = z.getNextEntry()) != null) {
                String n = e.getName();
                if (n.endsWith(".jar")) continue;
                if (!n.endsWith(".class") || n.contains("/client/") || n.contains("/mixin/")) continue;
                byte[] b = z.readAllBytes();
                ClassReader cr = new ClassReader(b);
                boolean[] clientOnly = {false};
                Set<String> refs = new TreeSet<>();
                cr.accept(new ClassVisitor(Opcodes.ASM9) {
                    public AnnotationVisitor visitAnnotation(String d, boolean v) {
                        if (d.contains("Environment") || d.contains("OnlyIn")) clientOnly[0] = true;
                        return null;
                    }
                    public MethodVisitor visitMethod(int acc, String name, String desc, String sig, String[] ex) {
