                String cn = cr.getClassName();
                String simple = cn.substring(cn.lastIndexOf('/') + 1);
                if (!clientOnly[0] && !refs.isEmpty() && !simple.matches(".*(Client|Renderer|Visual|Screen|Render|Overlay|Hud|Model|Particle|Sound|Ponder|Gui|Tooltip|Goggle|Debug|Inspector|Shader|Imgui|ImGui).*"))
                    out.put(cn, refs);
            }
        }
    }
}
