package dev.mcf.e2e;

import com.zurrtum.create.AllBlocks;
import com.zurrtum.create.content.contraptions.glue.SuperGlueEntity;
import com.zurrtum.create.content.kinetics.motor.CreativeMotorBlockEntity;
import dev.ryanhcode.sable.api.sublevel.SubLevelContainer;
import dev.ryanhcode.sable.sublevel.SubLevel;
import dev.simulated_team.simulated.content.blocks.physics_assembler.PhysicsAssemblerBlockEntity;
import dev.simulated_team.simulated.index.SimBlocks;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.FaceAttachedHorizontalDirectionalBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.AttachFace;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import org.joml.Quaterniondc;
import org.joml.Vector3d;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static dev.mcf.e2e.gametest.SimulatedTestHelper.findInPlot;
import static dev.mcf.e2e.gametest.SimulatedTestHelper.plotBlockEntity;

/**
 * The {@code boat} scenario ({@code -De2e.scenario=boat}, dedicated server): small propeller boats that take off from
 * flat ground, compared side by side for stability. Each variant is a 12x9 two-layer plank hull with lift rotors
 * (motor directly under a propeller bearing, sails glued on top), assembled with its physics assembler; the script runs
 * the rotors at full power (climb), half power (hover) and off (descend) and logs height and tilt of every boat.
 * Rotors with the bearing's thrust-direction option flipped spin the other way and still lift (counter-rotation).
 */
final class E2EBoat {
    private static final int GROUND = -60;
    private static final int FULL_TICK = 40, HALF_TICK = 240, OFF_TICK = 400, END_TICK = 560;

    private record Variant(String name, boolean twin, boolean gyro, String sail, boolean plus, boolean counter) {
    }

    private static final List<Variant> VARIANTS = List.of(
            new Variant("single-plain-createsail-3x3", false, false, "create:white_sail", false, false),
            new Variant("single-gyro-createsail-plus", false, true, "create:white_sail", true, false),
            new Variant("twin-gyro-createsail-counter", true, true, "create:white_sail", true, true),
            new Variant("single-gyro-symsail-plus", false, true, "simulated:white_symmetric_sail", true, false),
            new Variant("twin-gyro-symsail-counter", true, true, "simulated:white_symmetric_sail", true, true),
            new Variant("twin-gyro-symsail-same", true, true, "simulated:white_symmetric_sail", true, false));

    private final List<BlockPos> origins = new ArrayList<>();
    private final List<SubLevel> ships = new ArrayList<>();
    private final List<List<BlockPos>> motors = new ArrayList<>();
    private final List<double[]> maxTilt = new ArrayList<>();

    static boolean enabled() {
        return "boat".equals(System.getProperty("e2e.scenario"));
    }

    void tick(final ServerLevel level, final int since) {
        try {
            if (since == 1) {
                for (int i = 0; i < VARIANTS.size(); i++) {
                    final BlockPos origin = new BlockPos(-80 + 32 * i, GROUND + 1, 0);
                    this.origins.add(origin);
                    build(level, origin, VARIANTS.get(i));
                }
                E2E.LOG.info("E2E: boat built {} variants", VARIANTS.size());
            } else if (since == 20) {
                for (int i = 0; i < VARIANTS.size(); i++) {
                    this.assemble(level, i);
                }
            } else if (since == FULL_TICK) {
                this.setRotors(1.0);
            } else if (since == HALF_TICK) {
                this.setRotors(0.5);
            } else if (since == OFF_TICK) {
                this.setRotors(0.0);
            }
            if (since > 20 && since % 20 == 0) {
                for (int i = 0; i < this.ships.size(); i++) {
                    final SubLevel ship = this.ships.get(i);
                    if (ship == null) {
                        continue;
                    }
                    final double tilt = tiltDegrees(ship.logicalPose().orientation());
                    final double y = ship.logicalPose().position().y();
                    final double[] max = this.maxTilt.get(i);
                    final int phase = since < HALF_TICK ? 0 : since < OFF_TICK ? 1 : 2;
                    max[phase] = Math.max(max[phase], tilt);
                    E2E.LOG.info("E2E: boat t={} {} y={} tilt={}", since, VARIANTS.get(i).name(), String.format("%.1f", y), String.format("%.1f", tilt));
                }
            }
            if (since == END_TICK) {
                for (int i = 0; i < this.ships.size(); i++) {
                    final double[] max = this.maxTilt.get(i);
                    E2E.LOG.info("E2E: boat RESULT {} max tilt full={} half={} off={}", VARIANTS.get(i).name(),
                            String.format("%.1f", max[0]), String.format("%.1f", max[1]), String.format("%.1f", max[2]));
                }
            }
        } catch (final Throwable t) {
            E2E.LOG.error("E2E: boat scene FAILED at t={}", since, t);
        }
    }

    private static double tiltDegrees(final Quaterniondc q) {
        final Vector3d up = q.transform(new Vector3d(0, 1, 0));
        return Math.toDegrees(Math.acos(Math.max(-1, Math.min(1, up.y))));
    }

    private static Block block(final String id) {
        return BuiltInRegistries.BLOCK.getValue(Identifier.parse(id));
    }

    private static void build(final ServerLevel level, final BlockPos o, final Variant v) {
        // hull: x 0..11, z -4..4, two layers
        for (final BlockPos pos : BlockPos.betweenClosed(o.offset(0, 0, -4), o.offset(11, 1, 4))) {
            level.setBlockAndUpdate(pos, Blocks.OAK_PLANKS.defaultBlockState());
        }
        final int[] rotorZ = v.twin() ? new int[]{-3, 3} : new int[]{0};
        for (int r = 0; r < rotorZ.length; r++) {
            final BlockPos motor = o.offset(5, 2, rotorZ[r]);
            level.setBlockAndUpdate(motor, AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(BlockStateProperties.FACING, Direction.UP));
            final Block bearingBlock = block(v.gyro() ? "aeronautics:gyroscopic_propeller_bearing" : "aeronautics:propeller_bearing");
            level.setBlockAndUpdate(motor.above(), bearingBlock.defaultBlockState().setValue(BlockStateProperties.FACING, Direction.UP));
            if (v.counter() && r == 1) {
                // the second rotor spins the other way; flipping its thrust-direction option keeps it lifting
                final BlockEntity be = level.getBlockEntity(motor.above());
                if (be instanceof final com.zurrtum.create.foundation.blockEntity.SmartBlockEntity smart) {
                    smart.getAllBehaviours().stream()
                            .filter(b -> b instanceof com.zurrtum.create.foundation.blockEntity.behaviour.scrollValue.ServerScrollOptionBehaviour<?>)
                            .forEach(b -> ((com.zurrtum.create.foundation.blockEntity.behaviour.scrollValue.ServerScrollOptionBehaviour<?>) b).setValue(1));
                }
            }
            final BlockPos centre = motor.above(2);
            final BlockState sail = block(v.sail()).defaultBlockState().setValue(BlockStateProperties.FACING, Direction.UP);
            final int reach = v.plus() ? 2 : 1;
            for (int dx = -reach; dx <= reach; dx++) {
                for (int dz = -reach; dz <= reach; dz++) {
                    if (v.plus() && Math.abs(dx) == 2 && Math.abs(dz) == 2) {
                        continue;
                    }
                    if (v.plus() && Math.abs(dx) + Math.abs(dz) > 3) {
                        continue;
                    }
                    level.setBlockAndUpdate(centre.offset(dx, 0, dz), sail);
                }
            }
            level.setBlockAndUpdate(centre, Blocks.OAK_PLANKS.defaultBlockState());
            level.addFreshEntity(new SuperGlueEntity(level, new AABB(centre.getX() - reach, centre.getY(), centre.getZ() - reach,
                    centre.getX() + reach + 1, centre.getY() + 1, centre.getZ() + reach + 1)));
        }
        level.setBlockAndUpdate(o.offset(1, 2, 0), SimBlocks.PHYSICS_ASSEMBLER.defaultBlockState()
                .setValue(FaceAttachedHorizontalDirectionalBlock.FACE, AttachFace.FLOOR)
                .setValue(FaceAttachedHorizontalDirectionalBlock.FACING, Direction.NORTH));
        // hull, motors and bearings: one glue box (the sail layer has its own)
        level.addFreshEntity(new SuperGlueEntity(level, new AABB(o.getX(), o.getY(), o.getZ() - 4, o.getX() + 12, o.getY() + 4, o.getZ() + 5)));
    }

    private void assemble(final ServerLevel level, final int i) {
        final SubLevelContainer container = SubLevelContainer.getContainer(level);
        final Set<SubLevel> before = new HashSet<>(container.getAllSubLevels());
        SubLevel ship = null;
        if (level.getBlockEntity(this.origins.get(i).offset(1, 2, 0)) instanceof final PhysicsAssemblerBlockEntity assembler) {
            assembler.assembleOrDisassemble();
            for (final SubLevel subLevel : container.getAllSubLevels()) {
                if (!before.contains(subLevel)) {
                    ship = subLevel;
                }
            }
            if (ship == null) {
                E2E.LOG.error("E2E: boat {} assembly made no ship ({})", VARIANTS.get(i).name(), assembler.getLastAssemblyException());
            }
        }
        this.ships.add(ship);
        this.maxTilt.add(new double[3]);
        this.motors.add(ship == null ? List.of() : findInPlot(ship, s -> s.is(AllBlocks.CREATIVE_MOTOR)));
        if (ship != null) {
            E2E.LOG.info("E2E: boat {} assembled, {} motors, {} sails in plot", VARIANTS.get(i).name(), this.motors.get(i).size(),
                    findInPlot(ship, s -> s.is(block(VARIANTS.get(i).sail()))).size());
        }
    }

    private void setRotors(final double power) {
        for (int i = 0; i < this.ships.size(); i++) {
            final SubLevel ship = this.ships.get(i);
            if (ship == null) {
                continue;
            }
            final List<BlockPos> list = this.motors.get(i);
            for (int r = 0; r < list.size(); r++) {
                final CreativeMotorBlockEntity motor = plotBlockEntity(ship, list.get(r), CreativeMotorBlockEntity.class);
                if (motor == null) {
                    continue;
                }
                // -256 RPM lifts with the default thrust direction; a counter-rotating rotor runs +256 with its option flipped
                final int sign = VARIANTS.get(i).counter() && r == 1 ? 1 : -1;
                motor.generatedSpeed.setValue((int) Math.round(sign * 256 * power));
            }
        }
        E2E.LOG.info("E2E: boat rotors at {}%", (int) (power * 100));
    }
}

