import struct, zlib
def px(path):
    d = open(path, 'rb').read(); pos = 8; idat = b''; pal = trns = None
    while pos < len(d):
        ln, typ = struct.unpack('>I4s', d[pos:pos+8]); body = d[pos+8:pos+8+ln]; pos += 12 + ln
        if typ == b'IHDR': w, h, bd, ct = struct.unpack('>IIBB', body[:10])
        elif typ == b'PLTE': pal = [tuple(body[i:i+3]) for i in range(0, len(body), 3)]
        elif typ == b'tRNS': trns = list(body)
        elif typ == b'IDAT': idat += body
    raw = zlib.decompress(idat); bpp = 4 if ct == 6 else 1; stride = (w * bpp * bd + 7) // 8; out = []; prev = bytearray(stride); i = 0
    for y in range(h):
        f = raw[i]; line = bytearray(raw[i+1:i+1+stride]); i += 1 + stride; b = max(1, bpp * bd // 8)
        for x in range(stride):
            a = line[x-b] if x >= b else 0; up = prev[x]; c = prev[x-b] if x >= b else 0
            p = a + up - c; pr = a if abs(p-a) <= abs(p-up) and abs(p-a) <= abs(p-c) else (up if abs(p-up) <= abs(p-c) else c)
            line[x] = (line[x] + [0, a, up, (a+up)//2, pr][f]) & 255
        prev = line
        for x in range(w):
            if ct == 6: r, g, bl, al = line[x*4:x*4+4]
            else:
                if bd == 8: k = line[x]
                else: k = (line[x*bd//8] >> (8 - bd - (x*bd) % 8)) & ((1 << bd) - 1)
                r, g, bl = pal[k]; al = trns[k] if trns and k < len(trns) else 255
            out.append((r, g, bl, al) if al else (0, 0, 0, 0))
    return out
a, b = px('skin.png'), px('alt.png')
print('identical pixels:', a == b, 'diff count:', sum(1 for x, y in zip(a, b) if x != y))
